// Backdrop images embedded as base64 JPEG (generated by tools/bg on the laptop; see tools/bg/sheet.png).
// Embedded so the look never depends on bundle resource lookup (LiveContainer runs the app with a foreign Bundle.main).
import UIKit

enum EmbeddedBackdrops {
    static let lounge = ""
    static let office = ""
    static let neon = ""

    static func image(_ name: String) -> UIImage? {
        let b64: String
        switch name { case "lounge": b64 = lounge; case "office": b64 = office; case "neon": b64 = neon; default: return nil }
        guard let data = Data(base64Encoded: b64) else { return nil }
        return UIImage(data: data)
    }
}
